<?php

declare(strict_types=1);

use App\Domain\Instance\Release\ManifestSchema;
use App\Domain\Instance\Release\ReleaseManifest;
use Tests\Support\Docker\ReleaseHarness;
use Tests\Support\Docker\TestImage;

/*
 * U7 / M9-T06: build, sign and serve a release in the local harness (R1–R4, R8, E14, E18, KTD22, KTD23,
 * ADR 0064, ADR 0067). One harness release is published for the whole file: the app image (APP_VERSION
 * 2.1.0-alpha.1-test, SBOM and provenance) and every third-party pin mirrored by digest into `registry:3`, the
 * manifest generated by `release:manifest`, signed with a per-run local key and served under dist/. The
 * install itself is U5's J1. Skips only when Docker is unreachable; FIELDSET_REQUIRE_DOCKER=1 makes that a failure.
 */

beforeAll(function (): void {
    if (TestImage::dockerUnavailableReason() !== null) {
        return;
    }

    try {
        $GLOBALS['fieldsetHarness'] = ReleaseHarness::start();
        $GLOBALS['fieldsetHarnessRelease'] = $GLOBALS['fieldsetHarness']->publish(ReleaseHarness::TEST_VERSION);
    } catch (Throwable $exception) {
        $GLOBALS['fieldsetHarnessError'] = $exception;
    }
});

afterAll(function (): void {
    if (isset($GLOBALS['fieldsetHarness'])) {
        $GLOBALS['fieldsetHarness']->stop();
    }

    unset($GLOBALS['fieldsetHarness'], $GLOBALS['fieldsetHarnessRelease'], $GLOBALS['fieldsetHarnessError']);
});

beforeEach(function (): void {
    $reason = TestImage::dockerUnavailableReason();
    if ($reason !== null) {
        expect(getenv('FIELDSET_REQUIRE_DOCKER'))->not->toBe('1', $reason);
        $this->markTestSkipped($reason.' (install journeys need a Docker engine)');
    }

    if (isset($GLOBALS['fieldsetHarnessError'])) {
        throw $GLOBALS['fieldsetHarnessError'];
    }

    $this->harness = $GLOBALS['fieldsetHarness'];
    $this->release = $GLOBALS['fieldsetHarnessRelease'];
});

it('generates a manifest that validates against the schema and lists every service by digest', function (): void {
    $json = (string) file_get_contents($this->release->manifestPath());
    $manifest = ReleaseManifest::fromJson($json, new ManifestSchema(TestImage::repository().'/distribution/manifest.schema.json'));

    expect($manifest->version->__toString())->toBe(ReleaseHarness::TEST_VERSION)
        ->and($manifest->channel()->value)->toBe('alpha')
        ->and($manifest->platforms)->toBe($this->release->platforms)
        ->and(array_keys($manifest->images))->toBe(ReleaseManifest::SERVICES)
        ->and($manifest->images['app']->pin->digest)->toBe($this->release->appDigest)
        ->and($manifest->images['app']->pin->name())->toBe('ghcr.io/beyerenrico/fieldset')
        ->and($json)->not->toContain('certificate');

    foreach ($manifest->images as $image) {
        expect($image->pin->digest)->toMatch('/^sha256:[a-f0-9]{64}$/');
    }
});

it('serves every manifest digest from the local registry', function (): void {
    $manifest = ReleaseManifest::fromJson((string) file_get_contents($this->release->manifestPath()), new ManifestSchema(TestImage::repository().'/distribution/manifest.schema.json'));

    foreach ($manifest->images as $service => $image) {
        $reference = $image->pin->pullReference($this->harness->registry());
        $pull = $this->harness->pull($reference);

        expect($pull->getExitCode())->toBe(0, "{$service}: {$reference}\n".$pull->getErrorOutput());
    }
});

it('signs the manifest with the local key, verified by the pinned cosign image that install.sh and fieldset use', function (): void {
    $verify = $this->harness->cosign->verifyBlob($this->release->manifestPath(), $this->release->bundlePath());

    expect($verify->getExitCode())->toBe(0, $verify->getErrorOutput())
        ->and($verify->getErrorOutput())->toContain('Verified OK');
});

it('fails verification for a tampered manifest', function (): void {
    $tampered = $this->harness->directory.'/tampered-'.ReleaseHarness::MANIFEST;
    $data = $this->release->manifest();
    $data['images']['app']['digest'] = 'sha256:'.str_repeat('0', 64);
    file_put_contents($tampered, json_encode($data, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES)."\n");

    $process = $this->harness->cosign->verifyBlob($tampered, $this->release->bundlePath());

    expect($process->getExitCode())->not->toBe(0)
        ->and($process->getErrorOutput())->toContain('invalid signature');
});

it('signs the app image recursively and attaches SBOM and provenance attestations', function (): void {
    $verify = $this->harness->cosign->verifyImage($this->release->appReference);
    $index = json_decode((string) file_get_contents('http://'.$this->harness->registry().'/v2/beyerenrico/fieldset/manifests/'.$this->release->appDigest, false, stream_context_create([
        'http' => ['header' => 'Accept: application/vnd.oci.image.index.v1+json'],
    ])), true);
    $attestations = array_filter($index['manifests'], fn (array $entry): bool => ($entry['annotations']['vnd.docker.reference.type'] ?? null) === 'attestation-manifest');

    expect($verify->getExitCode())->toBe(0, $verify->getErrorOutput())
        ->and($attestations)->toHaveCount(count($this->release->platforms));
});

it('publishes only its own tag for a pre-release and never moves latest', function (): void {
    $tags = array_values(array_filter($this->harness->tags('beyerenrico/fieldset'), fn (string $tag): bool => ! str_starts_with($tag, 'sha256-')));

    expect($tags)->toBe([ReleaseHarness::TEST_VERSION])
        ->and(is_dir($this->harness->distDirectory().'/latest'))->toBeFalse();
});

it('serves the release assets and checksums like GitHub Releases', function (): void {
    $manifest = file_get_contents($this->release->url.'/'.ReleaseHarness::MANIFEST);
    $sums = (string) file_get_contents($this->release->url.'/SHA256SUMS');

    expect($manifest)->toBe(file_get_contents($this->release->manifestPath()))
        ->and($sums)->toContain(hash_file('sha256', $this->release->manifestPath()).'  '.ReleaseHarness::MANIFEST)
        ->and($sums)->toContain(hash_file('sha256', $this->release->bundlePath()).'  '.ReleaseHarness::MANIFEST.'.sigstore.json');
});
